(function(){'use strict';const $=id=>document.getElementById(id);let last='',infoReturn=null;
window.openBattleInfo=()=>{infoReturn=document.activeElement;const close=$('btn-close-battle-info');close.textContent='閉じる';close.setAttribute('aria-label','情報を閉じて対局に戻る');window.renderBattleActivations?.();const panel=$('modal-battle-info').querySelector('.editor-panel');if(panel)panel.scrollTop=0;pausePlayerOverlay();$('modal-battle-info').classList.remove('hidden');$('btn-close-battle-info').focus();};window.closeBattleInfo=()=>{$('modal-battle-info').classList.add('hidden');resumePlayerEngine();(infoReturn||$('btn-battle-info')).focus();};
function update(){const turn=isBattleEnded?'対局終了':soloBattlePending?'対局の準備':isPlayerTurn?'自分の番':'相手の番',mode=typeof autoBattleEnabled!=='undefined'&&autoBattleEnabled?'auto':isPlayerTurn?'self':'peer';const signature=turn+mode+battleMode+battleInputMode;if(last===signature)return;last=signature;$('mode-inspect').textContent=battleInputMode==='inspect'?'発射に戻る':'能力を見る';$('battle-turn-label').textContent=turn;$('battle-toolbar').dataset.turn=mode;$('result-score-label').textContent=battleMode==='friend'&&friendRoom?.mode==='online'?'対人RP':'段位ポイント';}
window.addEventListener('load',()=>{const top=document.createElement('div');top.className='battle-topline';$('battle-toolbar').prepend(top);top.append($('battle-turn-label'),$('btn-battle-menu'));$('btn-battle-menu').innerHTML='<span aria-hidden="true">☰</span> メニュー';$('btn-battle-menu').setAttribute('aria-haspopup','dialog');$('modal-battle-menu').querySelector('.editor-panel').append($('btn-battle-resume'));const overlay=document.createElement('div');overlay.id='modal-battle-info';overlay.className='editor-overlay hidden';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-labelledby','battle-info-title');overlay.innerHTML='<div class="editor-panel"><div class="editor-title"><h2 id="battle-info-title">対局の情報</h2><button id="btn-close-battle-info" aria-label="情報を閉じて対局に戻る" onclick="closeBattleInfo()">閉じる</button></div><p>自分は青の実線、相手は赤の破線。文字の色は属性です。</p><div id="battle-info-content"></div></div>';document.body.append(overlay);for(const id of ['battle-order-status','battle-legend','battle-matchup'])$('battle-info-content').append($(id));const footer=document.createElement('div');footer.id='battle-action-bar';$('arena-container').after(footer);footer.append($('central-shot-status'),$('battle-controls'));const info=document.createElement('button');info.id='btn-battle-info';info.textContent='情報';info.onclick=openBattleInfo;$('battle-controls').append(info);$('mode-inspect').onclick=()=>setBattleInputMode(battleInputMode==='inspect'?'shoot':'inspect');const name=$('battle-self-name');name.setAttribute('aria-label','自分のプレイヤー名');$('battle-guide').hidden=true;setInterval(update,150);update();requestAnimationFrame(resizeArena);});document.addEventListener('keydown',e=>{if(!$('modal-battle-info')||$('modal-battle-info').classList.contains('hidden'))return;if(e.key==='Escape'){e.preventDefault();closeBattleInfo();}if(e.key==='Tab'){const buttons=[...$('modal-battle-info').querySelectorAll('button')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});})();

document.addEventListener('pointerdown',e=>{const hud=document.getElementById('kanji-param-hud');if(hud&&!hud.hidden&&!hud.contains(e.target)){inspectedBody=null;hideBattleStats();}const detail=document.getElementById('modal-piece-detail');if(e.target===detail&&!detail.classList.contains('hidden'))closePieceDetail();},true);
